codes = {'C92.1': 'leucémie myéloïde chronique BCR::ABL1 positive', 'C92.5': 'leucémie aiguë myélomonocytaire (M4)', 'C93.0': 'leucémie monoblastique ou monocytaire aiguë', 'C93.1': 'leucémie myélomonocytaire chronique', 'C93.3': 'leucémie myélomonocytaire juvénile', 'C93.7': 'autres leucémies monocytaires', 'C93.9': 'leucémie monocytaire sans précision', 'C95.8': 'code additionnel : leucémie réfractaire à l’induction standard'}
for c, t in codes.items():
    d(c, [(c, 'code CIM-10-GM 2024 : ' + t)], 'Code CIM-10-GM ' + c, t[0].upper() + t[1:] + '.', 'c93-nosologie')
for base in ['C93.0', 'C93.1', 'C93.3', 'C93.7', 'C93.9']:
    for s, lab in (('0', 'sans mention de rémission complète'), ('1', 'en rémission complète')):
        c = base + s
        d(c, [(c, 'code CIM-10-GM 2024 à cinq caractères : ' + codes[base] + ', ' + lab)], 'Code CIM-10-GM ' + c, codes[base][0].upper() + codes[base][1:] + ', ' + lab + '.', 'c93-nosologie')
